        check("paper vs scissors", "b", RockPaperScissors.rpsWinner("paper", "scissors"));
        check("rock vs rock", "tie", RockPaperScissors.rpsWinner("rock", "rock"));
        check("paper vs paper", "tie", RockPaperScissors.rpsWinner("paper", "paper"));
