public class RockPaperScissors {

    public static String rpsWinner(String a, String b) {
        if (a.equals(b)) {
            return "tie";
        }
        boolean aWins = (a.equals("rock") && b.equals("scissors"))
                || (a.equals("scissors") && b.equals("paper"))
                || (a.equals("paper") && b.equals("rock"));
        return aWins ? "a" : "b";
    }
}
